function UIFishPoolGoFishingDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local goodsId = FishingUtils.GetCurUseCurrency(self._curFishingPlaceId, ConstantsFishing.ActivityType.Summer)
        if checkNumber(goodsId) == Constants.Currency.FishConsume then
            CfUtils.PlayAnimator(self.BtnFishingGroup.transform:Find("AnimRoot"), "Show")
        else
            CfUtils.PlayAnimator(self.BtnFishingGroup.transform:Find("AnimRoot"), "Show2")
        end
        coroutine.yield(WaitForSeconds(0.05))
        cs_coroutine.start(function()
            UIRaycastBlocker:AddCondition("UIFishPoolGoFishingShowNode2")
            coroutine.yield(WaitForSeconds(0.5))
            local isActivity = FishingUtils.IsFishPlaceActivitying(self._curFishingPlaceId)
            if isActivity then
                local vo = FishingUtils.GetFishActivityPlanVo(self._activityId)
                local luaPath = ""
                if checkNumber(vo.activity) == ConstantsFishing.ActivityType.KingChallenge then
                    luaPath = "Game.UI.Fishing.UIFishPoolGoFishingDialog.UIFishPoolGoFishingNode2"
                end
            
                local scr = CfUtils.GetLuaScr(self._activityGo, luaPath)
                if scr then 
                    scr:OnShow()
                end
            end
            UIRaycastBlocker:RemoveCondition("UIFishPoolGoFishingShowNode2")

            self:AutoFishBegin()
        end)

        local camGo = FishingMgr:GetInstance():GetSceneCam()
        if not isNull(camGo) then
            local urpBase = camGo:GetComponent(typeof(URPBaseCamera))
            urpBase:CopyCamera() 
        end
    end))
    return coWait
end

function UIFishPoolGoFishingDialog:AutoFishBegin()
    if not FishingUtils.IsAutoing() then
        return
    end
    CS.UnityEngine.Time.timeScale = FishingUtils.GetAutoSpeed()

    --上次设置的自动结束了
    if fishingComponent:GetIsAutoEnd() then
        fishingComponent:SetAutoing(false)

        print(self._notEnough)
        self._isNotClearScene = true
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishPoolAutoSettlementDialog, parameters = {isNotEnough = self._notEnough, isFail = self._isFail, isHandExit = self._isEndAuto}}, {
            {id = Constants.UITypeIds.UIFishPoolGoFishingDialog}
        })
        return
    end

    self:CheckRod()
end

function UIFishPoolGoFishingDialog:CheckRod()
    local id = fishingComponent:GetCurEquipRodId(self._curFishingPlaceId)
    local vo = FishingUtils.GetFishingGoodsVoById(id)
    if checkNumber(vo.durability) > 0 then
        local dojo = FishingUtils.GetFishingGoodsDojo(id)
        if dojo then
            --需要修
            if checkNumber(dojo.durability) == 0 then
                local isAutoFix = (checkNumber(KCookie.Get("FishAutoFix")) == 1)
                if isAutoFix then
                    local consumeNum = FishingUtils.GetFixConsumeNum(id)
                    local isCanFix = (GoodsUtils.GetThingNo(vo.fixCurrency) >= checkNumber(consumeNum))
                    if not isCanFix then
                        self._notEnough = true
                        fishingComponent:AutoFishEndReq(function()
                            self:AutoFishBegin()
                        end)
                    else
                        fishingComponent:FishingFixReq(id, function()
                            self:CheckWheel()
                        end)
                    end
                else
                    fishingComponent:AutoFishEndReq(function()
                        self:AutoFishBegin()
                    end)
                end
            else
                self:CheckWheel()
            end
        end
    else
        self:CheckWheel()
    end
end

function UIFishPoolGoFishingDialog:CheckWheel()
    if self._fixCo then
        cs_coroutine.stop(self._fixCo)
        self._fixCo = nil
    end
    
    local id = fishingComponent:GetCurEquipReelId(self._curFishingPlaceId)
    local vo = FishingUtils.GetFishingGoodsVoById(id)
    if checkNumber(vo.durability) > 0 then
        local dojo = FishingUtils.GetFishingGoodsDojo(id)
        if dojo then
            --需要修
            if checkNumber(dojo.durability) == 0 then
                local isAutoFix = (checkNumber(KCookie.Get("FishAutoFix")) == 1)
                if isAutoFix then
                    local consumeNum = FishingUtils.GetFixConsumeNum(id)
                    local isCanFix = (GoodsUtils.GetThingNo(vo.fixCurrency) >= checkNumber(consumeNum))

                    self._fixCo = cs_coroutine.start(function()
                        coroutine.yield(WaitForSeconds(1))
                        if not isCanFix then
                            self._notEnough = true
                            fishingComponent:AutoFishEndReq(function()
                                self:AutoFishBegin()
                            end)
                        else
                            fishingComponent:FishingFixReq(id, function()
                                self:FishAutoBegin()
                            end)
                        end
                    end)
                else
                    fishingComponent:AutoFishEndReq(function()
                        self:AutoFishBegin()
                    end)
                end
            else
                self:FishAutoBegin()
            end
        end
    else
        self:FishAutoBegin()
    end
end

function UIFishPoolGoFishingDialog:FishAutoBegin()
    self:OnBtnBeginCasting(true)

    if self._autoCo then
        cs_coroutine.stop(self._autoCo)
        self._autoCo = nil
    end
    self._autoCo = cs_coroutine.start(function()
        coroutine.yield(WaitForSeconds(2))
        self:OnBtnThrowPole(true)
    end)
end


function UIFishPoolGoFishingDialog:Awake()
    if not IsNull(ScreenTouchEffectModule) then
        KTool.SetActive(ScreenTouchEffectModule.Instance.gameObject, false)
    end
    self.EventFishFinish = Events.AddListener(Constants.EventNames.FishFinish, Bind(self, self.OnFishFinish))
    self.EventFishGoodsChange = Events.AddListener(Constants.EventNames.FishGoodsChange, Bind(self, self.OnFishGoodsChange))
    self.EventFishActive = Events.AddListener(Constants.EventNames.FishActive, Bind(self, self.OnFishActive))
    self.EventFishActivityCurrencyChange = Events.AddListener(Constants.EventNames.FishActivityCurrencyChange, Bind(self, self.OnFishActivityCurrencyChange))

    local proxy = UIEventProxy.Create(self.BtnLeave.gameObject)
    proxy.onPointerDown = Bind(self, self.OnPointDown)
    proxy.onPointerUp = Bind(self, self.OnPointUp)

    local proxy2 = UIEventProxy.Create(self.ThrowPole.gameObject)
    proxy2.onPointerDown = Bind(self, self.OnBtnThrowPole, false)
    --SetButtonAction(self.ThrowPole, Bind(self, self.OnBtnThrowPole))

    SetButtonAction(self.BtnFishAtlas, Bind(self, self.OnBtnIllustratedBook))
    SetButtonAction(self.BtnLevelOfFish, Bind(self, self.OnBtnLevel))
    --SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnFishBackPack))
    SetButtonAction(self.BtnAccompanyFishing, Bind(self, self.OnSelectAccompanyCard))
    SetButtonAction(self.BtnFishingGroup, Bind(self, self.OnBtnBeginCasting, false))
    SetButtonAction(self.BtnAutoFish, Bind(self, self.OnBtnAutoFish))
    self.EventMonthCardStop = Events.AddListener(Constants.EventNames.OnMonthCardExpired, Bind(self, self.OnMonthCardStop))

    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    if isNull(self._behaviourAction) then 
        self._behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
        self._behaviourAction.UpdateAction = function()
            self:OnUpdate()
        end
    end
    self._maxTalkTime = FishingUtils.GetTalkTime()
    self._circleLoopTime = FishingUtils.GetFishQTELoopTime()
    self._curFishingPlaceId = checkNumber(argument.fishingPlaceId)    --钓场id

    local vo = checkTable(argument.goodsVo)
    self._targetFishId = checkNumber(vo.id)    --目标鱼id
    print(table.dump(vo))

    self:FillFishingInfo()
    self:FillAccompanyCardInfo()
    self:FillFishingPropsInfo()

    self:FillActivityInfo()
    self:FillTips()

    FishingMgr:GetInstance():ChangeRodModel(checkNumber(fishingComponent:GetCurEquipRodId(self._curFishingPlaceId)))
end

function UIFishPoolGoFishingDialog:FillTips()
    local isShow = checkNumber(self._targetFishId) > 0
    if not isShow then
        return
    end
    SetButtonAction(self.BtnTips, function()
        if self._isClickHide then 
            return
        end
        self._isClickHide = true
        CfUtils.PlayAnimation(self.RemindTips, "FishPoolGoFishingDialog_RemindTips_Back")
    end)
    CfUtils.SetActive(self.RemindTips, isShow)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._targetFishId)
    CfUtils.FillText(self.TextDesc1, localize("本次目标:<color=#ff46bd>_name_</color>", {_name_ = vo.name}))
    vo = FishingUtils.GetFishingSpeciesVo(self._targetFishId)
    vo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.recommendBait)
    if vo then
        CfUtils.FillText(self.TextDesc2, localize("推荐使用:<color=#ff46bd>_name_</color>", {_name_ = vo.name}))
    end 
end

--绘制活动信息
function UIFishPoolGoFishingDialog:FillActivityInfo()
    local isActivity = FishingUtils.IsFishPlaceActivitying(self._curFishingPlaceId)
    if not isActivity then
        return
    end

    local data = FishingUtils.GetFishPlaceDojoActivityData(self._curFishingPlaceId)
    if not data then
        return
    end

    self._activityId = checkNumber(data.contentId)

    local vo = FishingUtils.GetFishActivityPlanVo(self._activityId)
    if not vo then
        return
    end

    self._activityLoader = ResourceModule.LoadBundleSync("Prefabs/FishPool/FishPoolActivityMainNode"..vo.changeId..".prefab", nil, true)
    if self._activityLoader and self._activityLoader.IsSuccess then
        self._activityGo = CS.UnityEngine.GameObject.Instantiate(self._activityLoader.ResultObject)
        KTool.SetParent(self._activityGo, self.controller.gameObject.transform:Find("Container").gameObject, false)

        KTool.SetActive(self._activityGo, true)
    else
        self._activityLoader:Release()
    end

    if isNull(self._activityGo) then
        return
    end

    local luaPath = ""
    if checkNumber(vo.activity) == ConstantsFishing.ActivityType.Summer then
        luaPath = "Game.UI.Fishing.UIFishPoolGoFishingDialog.UIFishPoolGoFishingNode1"
    elseif checkNumber(vo.activity) == ConstantsFishing.ActivityType.KingChallenge then
        luaPath = "Game.UI.Fishing.UIFishPoolGoFishingDialog.UIFishPoolGoFishingNode2"
    end

    local scr = CfUtils.GetLuaScr(self._activityGo, luaPath)
    if scr then 
        scr:Refresh(self._curFishingPlaceId, self)
    end

    self:OnFishActivityCurrencyChange()
end

function UIFishPoolGoFishingDialog:OnFishActivityCurrencyChange()
    --local data = FishingUtils.GetFishPlaceDojoActivityData(self._curFishingPlaceId, ConstantsFishing.ActivityType.Summer)
    --if not data then
    --    return
    --end

    local goodsId = FishingUtils.GetCurUseCurrency(self._curFishingPlaceId)
    if checkNumber(goodsId) <= 0 then
        return
    end

    self:FillFishConsume()
    CfUtils.PlayAnimation(self.FishStrength, "UIFishPoolGoFishingDialogActivelyBtnChange")
end

--刷新页面ui状态
function UIFishPoolGoFishingDialog:RefreshPageStatus(type)
    if type == PageStatus.Casting then 
        local dojo = fishingComponent:GetFishingPlaceDojo(self._curFishingPlaceId)
        if dojo then
            KTool.SetActive(self.LeftPanel, checkNumber(dojo.partner) ~= 0)
        end     
    elseif type == PageStatus.Ready then
        KTool.SetActive(self.LeftPanel, true)
    end

    KTool.SetActive(self.MonthCardNode, type == PageStatus.Ready)

    if self._isEndAuto then
        KTool.SetActive(self.AutoFishNode, false)
    else
        KTool.SetActive(self.AutoFishNode, type == PageStatus.Ready or (FishingUtils.IsAutoing() and type == PageStatus.Fishing))
    end

    KTool.SetActive(self.Main, type == PageStatus.Ready)
    KTool.SetActive(self.StartFishing, type == PageStatus.Fishing)
    KTool.SetActive(self.ThrowPole, type == PageStatus.Casting)
    KTool.SetActive(self.BtnFishingGroup, type == PageStatus.Ready)
    KTool.SetActive(self.BtnLeave, type == PageStatus.Fishing)
    KTool.SetActive(self.BtnLeave.transform:Find("ImgGroup/UIFX_FishPoolGoFishingDialogAutoFishPanel"), FishingUtils.IsAutoing() and type == PageStatus.Fishing)

    KTool.SetActive(self.FishingDefaultPanel, type ~= PageStatus.Casting)
    KTool.SetActive(self.PlaceName, type == PageStatus.Ready)

    if type ~= PageStatus.Casting then
        local goodsId = FishingUtils.GetCurUseCurrency(self._curFishingPlaceId, ConstantsFishing.ActivityType.Summer)
        if checkNumber(goodsId) == Constants.Currency.FishConsume then
            CfUtils.PlayAnimator(self.BtnFishingGroup.transform:Find("AnimRoot"), "Show")
        else
            CfUtils.PlayAnimator(self.BtnFishingGroup.transform:Find("AnimRoot"), "Show2")
        end
    else
        CfUtils.PlayAnimation(self.LeftPanel, "FishPoolGoFishingDialog_LeftPanel_Fishing")
    end

    local isActivity = FishingUtils.IsFishPlaceActivitying(self._curFishingPlaceId)
    if isActivity then
        CfUtils.SetActive(self._activityGo, type == PageStatus.Ready)
    else
        KTool.SetActive(self._activityGo, false)
    end

    --CfUtils.SetTopCommonActive(type == PageStatus.Ready, type == PageStatus.Ready)
    CfUtils.SetTopActive(type == PageStatus.Ready)

    self._curPageType = type

    local status = 1
    if self._curPageType == PageStatus.Ready then
        status = 1
        CfUtils.FillText(self.TextPullPole, localize("抛竿"))
        KTool.SetActive(self.BtnAccompanyFishing, true)
        CfUtils.PlayAnimation(self.LeftPanel, "FishPoolGoFishingDialog_LeftPanel_Fishing")
    elseif self._curPageType == PageStatus.Fishing then
        status = 2
        CfUtils.FillText(self.TextPullPole, localize("收杆"))

        local dojo = fishingComponent:GetFishingPlaceDojo(self._curFishingPlaceId)
        if dojo then
            KTool.SetActive(self.BtnAccompanyFishing, checkNumber(dojo.partner) ~= 0)
        else
            KTool.SetActive(self.BtnAccompanyFishing, false)
        end
    end
    CfUtils.SetUISwitchImage(self.ImgFishing, status)
    CfUtils.SetUISwitchImage(self.TextPullPole, status)
end

--绘制准备钓鱼前的信息
