--月卡到期
function UIFishPoolGoFishingDialog:OnMonthCardStop()
    self:FillAutoInfo()

    local isAutoing = FishingUtils.IsAutoing()
    if isAutoing then
        if not self._isEndAuto then
            CfUtils.PlayAnimation(self.FishingUnderway.transform:Find("Layout"), "FishPoolGoFishingDialogTextTermination")
            CfUtils.SetActive(self.AutoFishNode, false)
        end
        self._isEndAuto = true
    end
end

--自动钓鱼的信息
function UIFishPoolGoFishingDialog:FillAutoInfo()
    local isUnlockAuto = FishingUtils.IsUnlockAuto(self._curFishingPlaceId)
    CfUtils.SetUISwitchImage(self.ImgMonthCard, isUnlockAuto and 2 or 1)

    local isAutoing = FishingUtils.IsAutoing()
    local status = 1
    if not isUnlockAuto then
        status = 3
    else
        if isAutoing then
            status = 2
        else
            status = 1
        end
    end
    CfUtils.SetUISwitchImage(self.ImgLight, status)
    CfUtils.SetUISwitchText(self.Text, isAutoing and 2 or 1)
    CfUtils.SetActive(self.LockNode, not isUnlockAuto)
    CfUtils.SetActive(self.BtnAutoFishEffect, isAutoing)
    CfUtils.SetActive(self.ImgSymbol, isUnlockAuto)
    CfUtils.SetActive(self.FishingUnderway, isAutoing)

    SetButtonAction(self.BtnAdd, function()
        if FishingUtils.IsAutoing() then
            return
        end

        self._isNotClearScene = true
        local StoreUtils = import('Game.UI.Store.StoreUtils')
        StoreUtils.OpenMonthCard(nil, {{id = Constants.UITypeIds.UIFishPoolGoFishingDialog}})
    end)

    self:FillAutoNum()
end

function UIFishPoolGoFishingDialog:FillAutoNum()
    CfUtils.FillText(self.TextFrequency, localize("(剩余垂钓次数:_num_)", {_num_ = FishingUtils.GetRemainAutoNum()}))
end

--自动钓鱼
function UIFishPoolGoFishingDialog:OnBtnAutoFish()
    local isAutoing = FishingUtils.IsAutoing()
    --自动中    中途月卡消失也能点退出
    if isAutoing then
        if not self._isEndAuto then
            CfUtils.PlayAnimation(self.FishingUnderway.transform:Find("Layout"), "FishPoolGoFishingDialogTextTermination")
            CfUtils.SetActive(self.AutoFishNode, false)
        end
        self._isEndAuto = true
    else
        local isUnlock = FishingUtils.IsUnlockAuto(self._curFishingPlaceId)
        if not isUnlock then
            GameUtils.Toast(localize("当前渔场全图鉴解锁"))
            return
        end
        CfUtils.PlayAnimation(self.FishingUnderway.transform:Find("Layout"), "FishPoolGoFishingDialogTextIdle")

        self._isNotClearScene = true
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishPoolAutoChooseFrequencyDialog, parameters = {fishPlaceId = self._curFishingPlaceId}}, {
            {id = Constants.UITypeIds.UIFishPoolGoFishingDialog}
        })
    end
end

function UIFishPoolGoFishingDialog:FillFishConsume()
    local dojo = FishingUtils.GetFishingPlaceDojo(self._curFishingPlaceId)
    local num = dojo.collectNum
    local _, allFishNum = FishingUtils.GetAtlasGetNum(self._curFishingPlaceId)

    local num2 = checkNumber(num) / checkNumber(allFishNum) * 100
    CfUtils.FillText(self.BtnFishAtlas.transform:Find("Progress/TextNumber"), checkInt(num2).."%")

    local goodsId = FishingUtils.GetCurUseCurrency(self._curFishingPlaceId, ConstantsFishing.ActivityType.Summer)
    if checkNumber(goodsId) <= 0 then
        return
    end
    CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(goodsId))

    ---@type FishingPlaceVo
