--刷新说话
function UIFishPoolGoFishingDialog:RefreshRoleTalk(type, para)
    local mgc = self.TextCardBuff.gameObject:GetComponent(typeof(CS.Game.Native.Common.MultiplyGradientColor2)) 
    if mgc then
        mgc.StartPos = -1
        mgc.EndPos = -1
    end

    local dojo = fishingComponent:GetFishingPlaceDojo(self._curFishingPlaceId)
    if not dojo then
        return
    end
    local cardDojo = cardComponent:GetCardById(dojo.partner)
    if not cardDojo then
        KTool.SetActive(self.Dialogue2, false)
        return
    end

    local str = ""
    --钓鱼开始前
    if self._curPageType == PageStatus.Ready then
        local t = FishingUtils.GetFishCardBuffData(cardDojo.cardId, Constants.ChooseCardStatus.FishAccompany)
        if t then
            for k, v in pairs(t) do
                if checkNumber(cardDojo.star) >= checkNumber(v.starKey) then
                    str = str..FishingUtils.GetAdditionDesc(v.buffData).."\n"
                end
            end

            if string.isEmpty(str) then
                KTool.SetActive(self.Dialogue2, false)
                return
            else
                self._talkTime = self._maxTalkTime + 1
                KTool.SetActive(self.Dialogue2, true)
            end
        else
            KTool.SetActive(self.Dialogue2, false)
            return
        end
        --
    --钓鱼中
    else --if self._curPageType == PageStatus.Fishing then
        if checkNumber(type) > 0 then
            local vo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
            if vo then
                local talkId = FishingUtils.GetTalkIds(type, vo.characterId)
                local talkVo = FishingUtils.GetFishingTalkVo(talkId)
                local fishVo = GoodsConfMgr:GetInstance():GetGoodsVoById(para)
                if (checkNumber(talkVo.condition) == ConstantsFishing.TalkType.FishFailBreakFree or
                    checkNumber(talkVo.condition) == ConstantsFishing.TalkType.FishFailBreakLine or 
                     checkNumber(talkVo.condition) == ConstantsFishing.TalkType.FishFailDisOut) and
                      checkNumber(fishVo.quality) == 6 then
                    str = talkVo.content
                    local sT = CfUtils.Split(str, "_fishName_")
                    local f = utf8.len(sT[1])
                    if mgc then
                        mgc.StartPos = f
                        mgc.EndPos = f + utf8.len(fishVo.name) - 1
                    end
                    str = string.fmt(str, {_fishName_ = fishVo.name})
                else
                    str = FishingUtils.GetTalkStrById(talkId, para)
                end

                KTool.SetActive(self.Dialogue2, true)
                self._talkTime = 0
            end
        else
            KTool.SetActive(self.Dialogue2, false)
        end
    end
    CfUtils.FillText(self.TextCardBuff, str)
end

--绘制抛竿选择圆环界面
function UIFishPoolGoFishingDialog:FillSelectCircle()
    self:RefreshCircle()
    self.ImgYellowCircle.localScale = Vector3(1, 1, 1)
    self._updateCircleTime = 0
    self._dir = 1
    self._isUpdateCircle = true
    FishingMgr:GetInstance():ChangeRoleStatus(ConstantsFishing.RoleStatus.Cast)
    FishingMgr:GetInstance():RefreshAllPar()
end

function UIFishPoolGoFishingDialog:OnUpdate()
    self._talkTime = self._talkTime + CS.UnityEngine.Time.deltaTime
    if self._talkTime == self._maxTalkTime then
        KTool.SetActive(self.Dialogue2, false)
    end

    --黄色的圈圈
    if self._isUpdateCircle then
        self._updateCircleTime = self._updateCircleTime + (CS.UnityEngine.Time.deltaTime * self._dir) 
        if self._updateCircleTime >= self._circleLoopTime then
            self._dir = -1
            self._updateCircleTime = self._circleLoopTime
        elseif self._updateCircleTime <= 0 then
            self._dir = 1
            self._updateCircleTime = 0
        end
        local scale = self._updateCircleTime / self._circleLoopTime

        self.ImgYellowCircle.localScale = Vector3(scale, scale, scale)

        --引导 必当完美
        if self._isGuide then
            local type = self:GetCastRodType(self._updateCircleTime / self._circleLoopTime)
            if type == ConstantsFishing.CastRodType.Perfect then

                self._isUpdateCircle = false
                Events.Broadcast(Constants.EventNames.EVENT_GUIDE_WAIT_ANIMATE_EXECUTE_COMPLETE)
            end
        end
    elseif self._isBeginFishing then
        if self._enForceStop then
            return
        end
        FishingMgr:GetInstance():OnUpdata()
        self:UpdataReelPage()
    else
        FishingMgr:GetInstance():OnUpdataIdle()
    end

    if self._curPageType == PageStatus.Fishing then
        self:RefreshFishInfo()
        FishingMgr:GetInstance():RefreshLineRenderPos()

        if FishingUtils.IsAutoing() then
            local vo = FishingMgr:GetInstance():GetAutoTargetForceVo()
            if checkNumber(FishingMgr:GetInstance():GetCurForce()) <= (checkNumber(vo.maxWight) - checkNumber(vo.weight)) then
                FishingMgr:GetInstance():SetTieRod(true)
            elseif checkNumber(FishingMgr:GetInstance():GetCurForce()) >= (checkNumber(vo.maxWight)) then
                FishingMgr:GetInstance():SetTieRod(false)
            end
        end
    elseif self._curPageType == PageStatus.End then
    end
end

--刷新卷线仑图标旋转
function UIFishPoolGoFishingDialog:UpdataReelPage()
    local speed = FishingMgr:GetInstance():GetCurSpeed()
    local normalTieRod = FishingMgr:GetInstance():GetTieRod() and -1 or 1

    local ang = FishingUtils.GetReelRotTieSpeed() --15 * 2
    if normalTieRod == -1 then
        ang = FishingUtils.GetReelRotNotTieSpeed() ---15
    end
    ang = self.ImgPart_3.localRotation.eulerAngles.z + ang
    self.ImgPart_3.transform.localRotation = Quaternion.Euler(0, 0, ang)
end

--绘制圆环
function UIFishPoolGoFishingDialog:RefreshCircle()
    local defaultRect = self.ImgWhiteCircle.rect
    local defaultW, defaultH = defaultRect.width, defaultRect.height

    local prefectWeight = FishingUtils.GetPerfectWeight()
    local wellWeight = FishingUtils.GetWellWeight()
    local generallyWeight = FishingUtils.GetGenerallyWeight()
    local allWeight = prefectWeight + wellWeight + generallyWeight    --总权重

    local intervalStrs =  FishingUtils.GetPerfectAndWellInterval()
    local interval = CfUtils.Split(intervalStrs)                      --区间

    --先随良好圈外圈半径
    local wellOutRadius = math.random(checkNumber(interval[1]) + wellWeight, checkNumber(interval[2]) - wellWeight)
    local wellInRadius = wellOutRadius - wellWeight

    --陪钓人的加成
    local cardAddNum = FishingUtils.GetFishingAdditionValueByAccompanyCard(self._curFishingPlaceId, ConstantsFishing.AdditionType.AddCastRange)
    --[[
    local dojo = fishingComponent:GetFishingPlaceDojo(self._curFishingPlaceId)
    if dojo then
        if checkNumber(dojo.partner) ~= 0 then
            local t = FishingUtils.GetActiveCardBuffData(dojo.partner, Constants.ChooseCardStatus.FishAccompany) 
            for k, v in pairs(t) do
                cardAddNum = cardAddNum + v.buffData.value
            end
        end
    end
    ]]
    --完美圈加成
    prefectWeight = prefectWeight * (1 + FishingUtils.GetFishingPropsAdditionValue(ConstantsFishing.AdditionType.AddCastRange, nil, self._curFishingPlaceId) + cardAddNum)
    --随完美圈外圈半径
    local prefectOutRadius = math.random(checkInt(wellInRadius + prefectWeight), checkInt(wellOutRadius - prefectWeight))
    local prefectInRadius = prefectOutRadius - prefectWeight
    prefectOutRadius = wellInRadius + wellWeight / 2 + prefectWeight/2
    prefectInRadius = wellInRadius + wellWeight / 2 - prefectWeight/2

    self._castRodMap = {}
    local scaleOut = prefectOutRadius / allWeight
    self.ImgGreenCirceOut.sizeDelta = Vector2(defaultW * scaleOut, defaultH * scaleOut)
    local scaleIn = prefectInRadius / allWeight
    self.ImgGreenCirceIn.sizeDelta = Vector2(defaultW * scaleIn, defaultH * scaleIn)
    table.insert(self._castRodMap, {
        min = scaleIn,
        max = scaleOut,
        type = ConstantsFishing.CastRodType.Perfect
    })

    scaleOut = wellOutRadius / allWeight
    self.ImgBlueCircleOut.sizeDelta = Vector2(defaultW * scaleOut, defaultH * scaleOut)
    scaleIn = wellInRadius / allWeight
    self.ImgBlueCircleIn.sizeDelta = Vector2(defaultW * scaleIn, defaultH * scaleIn)
    table.insert(self._castRodMap, {
        min = scaleIn,
        max = scaleOut,
        type = ConstantsFishing.CastRodType.Well
    })

    KTool.SetActive(self.RingEffect, true)
end

