--初始化qte
function UIFishPoolGoFishingDialog:InitFishingQTEInfo()
    if self._isInitQTE then
        return
    end
    self._isInitQTE = true

    local t = FishingUtils.GetAllFishingPullPowerVo()
    self._maxWeight = FishingUtils.GetMaxPullPowerWeight()
    local curWeight = 0
    local value = 0
    for k, vo in pairs(t) do
        local go = self.Mask.transform:Find("ColorBar"..k)
        if go then
            local imageGo = go:GetComponent(typeof(Image))
            local num = checkNumber(vo.weight) / self._maxWeight
            curWeight = num + curWeight
            imageGo.fillAmount = curWeight * 0.37 + 0.32
            --[[
            local pos = go.transform.anchoredPosition
            go.transform.anchoredPosition = Vector3(posY, pos.x, 0)
            local rt = KTool.GetComponent(go,typeof(RectTransform))
            rt.sizeDelta = Vector2(checkNumber(vo.weight) * 0.01 * maxY, rt.sizeDelta.y)
            KTool.SetActive(go, true)
            CfUtils.SetColor(go, XLuaUtils.HexToColor("#"..vo.type))
            ]]

            if checkNumber(k) == 4 then
                self.ColorLight.transform.localRotation = Quaternion.Euler(0, 0,  -(180 * (curWeight * 0.37 + 0.32)) + 1.1)
            elseif checkNumber(k) == 5 then
                local num = curWeight * 0.37 + 0.32 - value
                local fill = self.ColorLight:GetComponent(typeof(Image))
                fill.fillAmount = num * 0.5
                self.ImgLineLight2.transform.localRotation = Quaternion.Euler(0, 0,  90 - 180 * num)
            end
            value = curWeight * 0.37 + 0.32
        end

        --[[
        local go = CfUtils.InstantiateGo(self.QTETip, self.QTETipPar)
        local pos = go.transform.anchoredPosition
        go.transform.anchoredPosition = Vector3(posY, pos.x, 0)
        if k == 1 then
            KTool.SetActive(go.transform:Find("TextNumber"), false)
        else
            CfUtils.FillText(go.transform:Find("TextNumber"), string.format("%.2f", vo.weight * 0.01 * maxY))
            CfUtils.FillText(go.transform:Find("TextNumber"), vo.desc)
        end
        KTool.SetActive(go, true)
        ]]
    end
end

--设置当前的qte
function UIFishPoolGoFishingDialog:SetCurQTEPos(force)
    if force <= 0 then
        force = 0 
    elseif force >= self._maxWeight then
        force = self._maxWeight
    end

    --self.ImgFishPole.fillAmount = 
    local ang = (force / self._maxWeight) * 64 - 32
    self.ImgFishPole.transform.localRotation = Quaternion.Euler(0, 0, -ang)
    --[[
    local maxY = self.ColorBarNode.rect.width
    local pos = self.QTESlider.transform.anchoredPosition
    self.QTESlider.transform.anchoredPosition = Vector3(force / self._maxWeight, pos.y, 0)
    ]]
end

