--刷新鱼的状态
function UIFishPoolGoFishingDialog:RefreshFishInfo()
    local screenW = CS.Engine.UI.UIModule.RootCanvas.transform.sizeDelta.x
    local screenH = CS.Engine.UI.UIModule.RootCanvas.transform.sizeDelta.y

    local pos = CfUtils.WorldPosition2UIPosition(FishingMgr:GetInstance():GetFishGo().transform.position, self.StartFishing.transform)

    local fPos = CfUtils.UIWorldToScreenPos(self.ImgarrowPar)  --self.Imgarrow.transform.position
    local tPos = Vector3(pos.x, pos.y, 0)
    local ang = 180 - CfUtils.AngleY(fPos, tPos)    --指标位置到鱼的位置的夹角

    pos = pos + Vector2(0, 130)

    local x = math.min(math.abs(pos.x), screenW/2)
    local normalPos = Vector3(190.92, -14.65502, 0)

    local screenRect = CS.UnityEngine.Rect(0, 0, screenW, screenH);
    local isInRect = screenRect:Contains(pos + Vector2(screenW/2, screenH/2))

    if math.abs(pos.x) >= screenW/2 - 135 then
        --右边
        if pos.x > 0 then
            normalPos = Vector3(-105.07, -14.65502, 0)
        end
    end
    
    if math.abs(pos.x) >= screenW/2 then
        --右边
        if pos.x > 0 then
            x = x - self.FishInScreen.rect.width/2 - 30
            normalPos = Vector3(-105.07, -14.65502, 0)
        --左边
        else
            x = -x + self.FishInScreen.rect.width/2 + 30
        end
    else
        x = pos.x
    end

    local y = math.min(math.abs(pos.y), screenH/2)
    if math.abs(pos.y) >= screenH/2 then
        --上边
        if pos.y > 0 then
            y = y - self.FishInScreen.rect.height/2
        --下边
        else
            y = y + self.FishInScreen.rect.height/2
        end
    else
        y = pos.y
    end

    if not isInRect then
        y = self.FishInScreen.transform.localPosition.y
    end
    self.FishInScreen.transform.localPosition = Vector3(x, y, 0)   
    self.ImgarrowPar.transform.localRotation = Quaternion.Euler(0, 0, ang)
    --self.BloodGroup.transform.localPosition = normalPos

    --播结束的动画了已经
    if self._isPlayEndAni then
        return
    end

    local force = FishingMgr:GetInstance():GetCurForce()
    self:SetCurQTEPos(force)
    local hpPercentage = FishingMgr:GetInstance():GetHpPercentage()
    self.ImgFishBlood.fillAmount = hpPercentage
    CfUtils.FillText(self.TextDistance, string.format("%.2f", FishingMgr:GetInstance():GetCurDistance()).."M")
    CfUtils.SetUISwitchImage(self.ImgFishBlood, (hpPercentage <= FishingUtils.GetFishHpColorChange()) and 2 or 1)
    self.DropBloodGroup.value = hpPercentage

    local vo = FishingUtils.GetFishingPullPowerVoByForce(force)
    if vo then
        if checkNumber(vo.id) > 4 then
            CfUtils.SetColor(self.TxtNumber, XLuaUtils.HexToColor("#"..vo.type))
        else
            CfUtils.SetColor(self.TxtNumber, XLuaUtils.HexToColor("#ffffff"))
        end
        CfUtils.FillText(self.TxtNumber, vo.desc)

        --[[
        if checkNumber(self._lastDamageId) ~= checkNumber(vo.id) then
            CfUtils.PlayAnimator(self.ImgHit, "Play")
        end
        ]]
        --KTool.SetActive(self.PerfectNode, checkNumber(vo.id) == 5)
        --KTool.SetActive(self.RingEffect, checkNumber(vo.id) == 5)

        self._lastDamageId = checkNumber(vo.id)
    end

    local status = FishingMgr:GetInstance():GetCurFishStatus()
    KTool.SetActive(self.TxtEscape, status == ConstantsFishing.FishStatus.RunAway)

    if checkNumber(self._curStatus) ~= status then 
        if status == ConstantsFishing.FishStatus.RunAway then
            CfUtils.PlayAnimator(self.FishInGroupHit, "Danger")
        else
            CfUtils.PlayAnimator(self.FishInGroupHit, "Normal")
        end
        self._curStatus = status
    end
end

--开始钓鱼
function UIFishPoolGoFishingDialog:OnBtnBeginCasting(isAuto)
    self._isNotCanClick = true
    if FishingUtils.IsAutoing() and not isAuto then
        return
    end

    if not (self._curPageType == PageStatus.Ready) then
        return
    end

    --进来的时候是否有活动
    if checkNumber(self._activityId) > 0 then
        --判断是否开启中
        local isOpen = FishingUtils.IsActivityOpen(self._curFishingPlaceId)
        if not isOpen then
            GameUtils.Toast(localize("活动已结束"))
            return
        end
    end

    local isCanFishing, err, errStatus = self:IsCanFishIng()
    if not isCanFishing and checkNumber(errStatus) == 1 then
        local vo = FishingUtils.GetFishingPlaceVo(self._curFishingPlaceId)
        local t = {
            goodsId = vo.properties,
            consumeGoodsId = vo.cost,
            remainTime = 0,
            consumeNum = vo.costNum,
            maxBuyNum = 999,
            buyCb = function(buyNum)
                GameUtils.Request(Interfaces.OverseaFishingExchangeTicket, {placeId = self._curFishingPlaceId, num = buyNum}, function(request, response)
                    if checkNumber(response.errCode) ~= 0 then
                        return
                    end
                    local jsonData = response.data
        
                    GoodsUtils.DrawRewards(jsonData.rewards, true)
                    GoodsUtils.DrawRewards({ { goodsId = vo.cost, num = -buyNum * checkNumber(vo.costNum)} })
                    self:FillFishConsume()
                end)
            end,
        }

        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = t}, {
        })
        --GameUtils.Toast(err)
        return
    elseif not isCanFishing then
        GameUtils.Toast(err)
        return
    end
    --刷新一下是否是引导
    self:RefreshIsGuide()

    cs_coroutine.start(function()
        CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_throw_ready)
        FishingMgr:GetInstance():ForceIdle()

        UIRaycastBlocker:AddCondition("UIFishPoolGoFishingDialog")
        local t = FishingUtils.GetFishingPropsList(self._curFishingPlaceId)
        for k, v in pairs(t) do
            if not FishingUtils.IsBaseProps(v) then
                local go = self.OptipnIconGroup.transform:Find("IconNode"..k)
                if go then
                    KTool.SetActive(go.transform:Find("TextNumber2"), true)
                end
            end
        end
        FishingMgr:GetInstance():SetSwingidle(true)

        CfUtils.PlayAnimator(self.Root, "Out")

        local goodsId = FishingUtils.GetCurUseCurrency(self._curFishingPlaceId)
        if checkNumber(goodsId) == Constants.Currency.FishConsume then
            CfUtils.PlayAnimator(self.BtnFishingGroup.transform:Find("AnimRoot"), "Out")
        else
            CfUtils.PlayAnimator(self.BtnFishingGroup.transform:Find("AnimRoot"), "Out2")
        end

        CfUtils.SetActive(self._activityGo, false)
        coroutine.yield(WaitForSeconds(0.8))
        for k, v in pairs(t) do
            local go = self.OptipnIconGroup.transform:Find("IconNode"..k)
            if go then
                KTool.SetActive(go.transform:Find("TextNumber2"), false)
            end
        end
        UIRaycastBlocker:RemoveCondition("UIFishPoolGoFishingDialog")

        self:RefreshPageStatus(PageStatus.Casting)
        self:FillSelectCircle()
    end)
end

--点击选中圆环
function UIFishPoolGoFishingDialog:OnBtnThrowPole(isAuto)
    if FishingUtils.IsAutoing() and not isAuto then
        return
    end


    self._isUpdateCircle = false
    if self._isThrowReq then
        return
    end
    self._isThrowReq = true

    local type = self:GetCastRodType(self._updateCircleTime / self._circleLoopTime)
    fishingComponent:FishingCastingReq(self._curFishingPlaceId, type, function(fishId)
        fishId = checkNumber(fishId)
        if type == ConstantsFishing.CastRodType.Perfect then
            CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_throw_perfect)
        elseif type == ConstantsFishing.CastRodType.Well then
            CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_throw_good)
        elseif type == ConstantsFishing.CastRodType.Generally then
            CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_throw_normal)
        end

        self._castCo = cs_coroutine.start(function()
            KTool.SetActive(self.ImgText, true)
            CfUtils.SetUISwitchImage(self.ImgStatus, type)

            local aniGo = self.UIFX_FishPoolGoFishingNormal
            if type == ConstantsFishing.CastRodType.Perfect then
                aniGo = self.UIFX_FishPoolGoFishingPerfect
            elseif type == ConstantsFishing.CastRodType.Well then
                aniGo = self.UIFX_FishPoolGoFishingGood
            end

            KTool.SetActive(aniGo, true)
            self:FillQTEBuff(type)
            coroutine.yield(WaitForSeconds(1))
            KTool.SetActive(self.ImgText, false)
            KTool.SetActive(aniGo, false)
            
            KTool.SetActive(self.ThrowPole, false)
            --播一下抛竿动作
            FishingMgr:GetInstance():SetSwingPar(type)            
            FishingMgr:GetInstance():SetPullPar(true)
            
            --说话
            local talkType = "10"..type
            self:RefreshRoleTalk(talkType, fishId)

            --KTool.SetActive(self.PerfectNode, type == ConstantsFishing.CastRodType.Perfect or true)

            local time = 1.2
            if type == ConstantsFishing.CastRodType.Perfect then
                time = 1.35
            elseif type == ConstantsFishing.CastRodType.Well then
                time = 1.5
            end
            coroutine.yield(WaitForSeconds(time))
            KTool.SetActive(self.PerfectNode, false)

            CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_bait)

            FishingMgr:GetInstance():SetShuiHuaEffectActive(true, type)
            KTool.SetActive(self.TipAnimNode, true)
            coroutine.yield(WaitForSeconds(1))
            FishingMgr:GetInstance():SetShuiHuaEffectActive(false)

            coroutine.yield(WaitForSeconds(0.5))
            KTool.SetActive(self.TipAnimNode, false)

            self:ClearQTEBuff()

            if fishId <= 0 then
                GameUtils.Toast(localize("没有鱼id"))
                self:FillFishingInfo()
            else
                self:RefreshBeginFishing(fishId, type)
            end

            --等初始化完
            coroutine.yield(WaitForSeconds(0.1))
            --打开前初始化第一帧的ui
            self:RefreshFishInfo()
            --初始化完再打开
            self:RefreshPageStatus(PageStatus.Fishing)
            CfUtils.PlayAnimator(self.Root, "Show")
        
            --一开始没伤害 
            CfUtils.FillText(self.TextDropBlood, "")
            FishingMgr:GetInstance():SetLineRenderActive(true)

            KTool.SetActive(self.BloodGroup, true)
            KTool.SetActive(self.TxtEscape, true)
            --这个地方只是ui打开之后纠正一次动画
            local status = FishingMgr:GetInstance():GetCurFishStatus()
            if status == ConstantsFishing.FishStatus.RunAway then
                CfUtils.PlayAnimator(self.FishInGroupHit, "Danger")
            else
                CfUtils.PlayAnimator(self.FishInGroupHit, "Normal")
            end

            --引导进来直接暂停
            if self._isGuide then
                self._enForceStop = true
                Events.Broadcast(Constants.EventNames.EVENT_GUIDE_WAIT_ANIMATE_EXECUTE_COMPLETE)
            end
            FishingMgr:GetInstance():ChangeRoleStatus(ConstantsFishing.RoleStatus.Fishing)
            self._isThrowReq = false
        end)
    end, function()
        self:FillFishingInfo()
        self._isThrowReq = false
    end)
end

--获取抛竿类型
function UIFishPoolGoFishingDialog:GetCastRodType(num)
    if not self._castRodMap then
        return ConstantsFishing.CastRodType.Generally
    end
    for k, v in pairs(self._castRodMap) do
        if num >= v.min and num <= v.max then 
            return v.type
        end
    end
    return ConstantsFishing.CastRodType.Generally
end

