--是否可以钓鱼
function UIFishPoolGoFishingDialog:IsCanFishIng()
    local err = ""
    local t = FishingUtils.GetFishingPropsList(self._curFishingPlaceId)
    for k, v in pairs(t) do
        local type = GoodsUtils.GetIdType(v)
        local dojo = FishingUtils.GetFishingGoodsDojo(v)
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(v)
        if dojo then
            if type == Constants.IDType.GoodsReel or type == Constants.IDType.GoodsFishingRod then
                if checkNumber(dojo.durability) == 0 then
                    if vo then
                        err = localize("_name_耐久不足", {_name_ = vo.name})
                    end
                    return false, err
                end
            elseif type == Constants.IDType.GoodsBait or type == Constants.IDType.GoodsFishingLine then
                if checkNumber(dojo.num) <= 0 then
                    if vo then
                        err = localize("_name_不足", {_name_ = vo.name})
                    end
                    return false, err
                end
            end
        else
            if vo then
                err = localize("_name_不足", {_name_ = vo.name})
            end
            return false, err
        end 

        local limitPlaceId = FishingUtils.GetFishGoodsLimitPlaceData(v)
        --物品的限制条件
        if limitPlaceId > 0 then
            local isUnlock, err = FishingUtils.IsUnlockLimitDatas({{
                limitId = ConstantsFishing.LimitType.FishPlace,
                limitValue = limitPlaceId
            }}, {fishPlaceId = self._curFishingPlaceId})
            if not isUnlock then
                return false, vo.name..err
            end
        end
    end

    --渔场限制条件
    local t = FishingUtils.GetPlaceLimitInfo(self._curFishingPlaceId)
    local isUnlock, err = FishingUtils.IsUnlockLimitDatas(t, {fishPlaceId = self._curFishingPlaceId})
    if not isUnlock then
        return false, err
    end

    --判断钓鱼货币
    ---@type FishingPlaceVo
    local placeVo = FishingUtils.GetFishingPlaceVo(self._curFishingPlaceId)
    if placeVo then
        local goodsId = FishingUtils.GetCurUseCurrency(self._curFishingPlaceId, ConstantsFishing.ActivityType.Summer)
        if checkNumber(goodsId) <= 0 then
            return
        end

        local num = GoodsUtils.GetThingNo(goodsId)
        if num < checkNumber(placeVo.num) then
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            if vo then
                return false, localize("_name_不足", {_name_ = vo.name}), 1
            end
        end
    end
    return true, ""
end

