--钓鱼结束
function UIFishPoolGoFishingDialog:OnFishFinish(body)
    --强制结束会有其他的逻辑
    if (body.isAutoStop) then
        return
    end

    --关掉点击拉杆的音乐
    CriWareUtils.RemoveCueSheet(UISheets.SFX_Fishing.path)
    CfUtils.FillText(self.TextDropBlood, "")

    if not body then
        return
    end
    local type = checkNumber(body.type)
    self:ClearQTEBuff()
    self._isBeginFishing = false

    local path = CS.UnityEngine.Application.dataPath
    function subString(str, k)
        local ts = string.reverse(str)
        local _, i = string.find(ts, k)
        local m = string.len(ts) - i + 1
        return string.sub(str, 1, m)  
    end
    path = subString(path, "/").."/Product/Lua/fish.txt"
    --写
    io.writeFile(path, FishingMgr:GetInstance()._writeStr)

    ---@type FishingPlaceVo
    local vo = FishingUtils.GetFishingPlaceVo(self._curFishingPlaceId)
    local goodsId = FishingUtils.GetCurUseCurrency(self._curFishingPlaceId, ConstantsFishing.ActivityType.Summer)

    local isUnlock1 = FishingUtils.IsUnlockAuto(self._curFishingPlaceId)
    --type = 1
    fishingComponent:FishingCastingOverReq(type, self._curFishingPlaceId, function(data, lastExp, lastLevel)
        UIRaycastBlocker:AddCondition("UIFishPoolGoFishingDialogFinish")

        self:FillAutoNum()

        self._finishCo = cs_coroutine.start(function()
            FishingMgr:GetInstance():SetSwingidle(false)

            FishingMgr:GetInstance():ChangeRoleStatus(ConstantsFishing.RoleStatus.FishEnd)
            local num, time = self:GetFinishStatusNum(type, body.forceScale, data)
            FishingMgr:GetInstance():SetFinishPar(math.max(num, time))

            --掉完的动画
            if type == ConstantsFishing.FishFinishType.Success then
                self:OnFishActivityCurrencyChange()
                CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_end)

                local dis = FishingMgr:GetInstance():GetCurDistance()

                local fishGo = FishingMgr:GetInstance():GetFishGo()
                local fPos = fishGo.transform.localPosition
                local tPos = Vector3(0, 0, 0)
                
                FishingMgr:GetInstance():HideShuiHuaEffect()
                self._isPlayEndAni = true
                CfUtils.PlayAnimator(self.FishInGroupHit, "Normal")
                KTool.SetActive(self.BloodGroup, false)
                KTool.SetActive(self.TxtEscape, false)

                KTool.SetActive(fishGo.transform:Find("fx_diaoyu_water03"), true)

                CfUtils.DoTween(1.5, function(value)
                    FishingMgr:GetInstance():RefreshLineRenderPos()
                    fishGo.transform.localPosition = CS.UnityEngine.Vector3.Lerp(fPos, tPos, value)
                    CfUtils.FillText(self.TextDistance, string.format("%.2f", (dis - dis*value)).."M")
                end)
                coroutine.yield(WaitForSeconds(1.5))
                self._isPlayEndAni = false

                if FishingUtils.GetFishRareNameByRare(data.rating) == "S" then
                    CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_pingji_s)
                end

                if FishingUtils.GetFishRareNameByRare(data.rating) == "S" then
                    local ani = fishGo.transform:GetComponent(typeof(Animator))
                    if not isNull(ani) then
                        KTool.SetActive(fishGo.transform:Find("fx_diaoyu_water03"), true)
                        ani.enabled = true
                        CfUtils.PlayAnimator(ani, "fx_diaoyu_water03")
                        coroutine.yield(WaitForSeconds(2.333))
                        ani.enabled = false
                        fishGo.transform.localPosition = Vector3(0, 0, 0)
                    end
                    self:RefreshPageStatus(PageStatus.End)
                    if not isNull(ani) then
                        KTool.SetActive(fishGo.transform:Find("fx_diaoyu_water03"), false)
                    end

                    CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_chushui)
                else
                    CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_chushui)
                    KTool.SetActive(fishGo.transform:Find("fx_diaoyu_water03"), true)
                    coroutine.yield(WaitForSeconds(0.3))
                    self:RefreshPageStatus(PageStatus.End)
                    KTool.SetActive(fishGo.transform:Find("fx_diaoyu_water03"), false)
                end

                FishingMgr:GetInstance():SetLineRenderActive(false)
                KTool.SetActive(fishGo.transform:Find("fx_diaoyu_water04"), true)
                if FishingUtils.GetFishRareNameByRare(data.rating) == "S" then
                    coroutine.yield(WaitForSeconds(0.7))
                else
                    coroutine.yield(WaitForSeconds(0.2))
                end
                KTool.SetActive(fishGo.transform:Find("fx_diaoyu_water04"), false)

                --coroutine.yield(WaitForSeconds(time - 1.5))
            else
                CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_stringless)
                FishingMgr:GetInstance():HideShuiHuaEffect()
                FishingMgr:GetInstance():SetLineRenderActive(false)
                self:RefreshPageStatus(PageStatus.End)

                coroutine.yield(WaitForSeconds(time))
            end
            FishingMgr:GetInstance():ChangeRoleStatus(ConstantsFishing.RoleStatus.Idle)

            local talkType = "20"..type
            self:RefreshRoleTalk(talkType, FishingMgr:GetInstance()._curFishId)

            self._isNotCanClick = false

            --成功
            if type == ConstantsFishing.FishFinishType.Success then
                self:FillActivityInfo()
                self:FillFishConsume()

                local go = GameUtils.GetRedPointGo(self.BtnFishAtlas)
                CfUtils.SetActive(go, FishingUtils.IsHaveCanDrawAtlasReward(self._curFishingPlaceId)) 
                
                --KTool.SetActive(self.controller.gameObject, false)

                self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 999)
                --- 按钮会多次点击 要钓鱼完成要关闭阻塞
                if self._isGuide then
                    Events.Broadcast(Constants.EventNames.EVENT_GUIDE_CLOSE_BLOCK)
                end

                CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_get_fish)

                --if FishingUtils.IsAutoing() then
                --    self:OnCloseGetDialog(lastExp, lastLevel)
                --    KTool.SetActive(self.controller.gameObject, true)
                --    local goodsId = FishingUtils.GetCurUseCurrency(self._curFishingPlaceId, ConstantsFishing.ActivityType.Summer)
                --    if checkNumber(goodsId) == Constants.Currency.FishConsume then
                --        CfUtils.PlayAnimator(self.BtnFishingGroup.transform:Find("AnimRoot"), "Show")
                --    else
                --        CfUtils.PlayAnimator(self.BtnFishingGroup.transform:Find("AnimRoot"), "Show2")
                --    end
                --else
                    CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishHarvestDisPlayPopupDialog, parameters = {fishPlaceId = self._curFishingPlaceId, data = data, lastExp = lastExp, lastLevel = lastLevel, closeCb = function()
                        self:OnCloseGetDialog(lastExp, lastLevel)
                        --KTool.SetActive(self.controller.gameObject, true)
                        self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)

                        local goodsId = FishingUtils.GetCurUseCurrency(self._curFishingPlaceId, ConstantsFishing.ActivityType.Summer)
                        if checkNumber(goodsId) == Constants.Currency.FishConsume then
                            CfUtils.PlayAnimator(self.BtnFishingGroup.transform:Find("AnimRoot"), "Show")
                        else
                            CfUtils.PlayAnimator(self.BtnFishingGroup.transform:Find("AnimRoot"), "Show2")
                        end

                        local isUnlock2 = FishingUtils.IsUnlockAuto(self._curFishingPlaceId)
                        if (isUnlock1 ~= isUnlock2) and isUnlock2 then
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishPoolAutoFishUnlockPopupDialog, parameters = {fishPlaceId = 1, cb = function()
                                if FishingUtils.IsAutoing() then
                                    if self._isEndAuto or (FishingUtils:GetRemainAutoNum() <= 0) then
                                        fishingComponent:AutoFishEndReq(function()
                                            self:AutoFishBegin()
                                        end)
                                    else
                                        self:AutoFishBegin()
