                                end

                                self._autoUnlockCo = cs_coroutine.start(function()
                                    CfUtils.SetActive(self.BtnAutoFish.transform:Find("UIFX_AutoFish"), true)
                                    coroutine.yield(WaitForSeconds(1.25))
                                    self:FillAutoInfo()
                                end)
                            end}}, {
