                --end
            elseif type == ConstantsFishing.FishFinishType.BreakLine then
                if FishingUtils.IsAutoing() then
                else
                    self:FillFailInfo(type)
                    coroutine.yield(WaitForSeconds(2))
                end
            elseif type == ConstantsFishing.FishFinishType.BreakFree then
