--关闭界面的回调
function UIFishPoolGoFishingDialog:OnCloseGetDialog(lastExp, lastLevel)
    self._getFishCo = cs_coroutine.start(function()
        --CfUtils.PlayAnimator(self.ImgCreel, "Play")

        local curLevel, curExp = FishingUtils.GetCurLevelAndExp()
        --升级
        if checkNumber(curLevel) > lastLevel then
            local needExp = FishingUtils.GetUpLevelExp(lastLevel)

            local showExp = FishingUtils.GetShowExpByLevelAndExp(lastLevel, lastExp)
            local dis = needExp - showExp 
            CfUtils.DoTween(0.4, function(value)
                local showExp = showExp + dis * value
                self.ImgRound.fillAmount = showExp/needExp --0.15 + showExp/needExp * (0.84 - 0.15) 
            end)
            coroutine.yield(WaitForSeconds(0.4))
            CfUtils.FillText(self.TxtLv, curLevel)

            local needExp = FishingUtils.GetUpLevelExp(curLevel)
            local dis = FishingUtils.GetShowExpByLevelAndExp(curLevel, curExp)

            CfUtils.DoTween(0.8, function(value)
                local showExp = 0 + dis * value
                self.ImgRound.fillAmount = showExp/needExp --0.15 + showExp/needExp * (0.84 - 0.15) 
            end)
        else
            local needExp = FishingUtils.GetUpLevelExp(curLevel)

            local dis = curExp - lastExp 
            local showExp = FishingUtils.GetShowExpByLevelAndExp(lastLevel, lastExp)
            CfUtils.DoTween(0.8, function(value)
                local showExp = showExp + dis * value
                self.ImgRound.fillAmount = showExp/needExp --0.15 + showExp/needExp * (0.84 - 0.15) 
            end)
        end
    end)
end

--结束时候动作的参数
function UIFishPoolGoFishingDialog:GetFinishStatusNum(type, forceScale, data)
    if type == ConstantsFishing.FishFinishType.BreakLine or type == ConstantsFishing.FishFinishType.DisExceed then
        return 41, 3.633
    elseif type == ConstantsFishing.FishFinishType.BreakFree then
        return 51, 3.333
    else
        local num = checkInt(forceScale / 0.75) + 1
    
        local isS = (FishingUtils.GetFishRareNameByRare(data.rating) == "S")
        if isS then
            --新获得
            --if checkNumber(data.isNew) == 1  then
                return 110 + num, 3.933
            --新纪录
            --elseif checkNumber(data.isNew) == 1  then
            --    return 120 + num, 3.933
            --else
            --    return 130 + num, 3.933
            --end
        else
            --新获得
            --if checkNumber(data.isNew) == 1  then
                return 10 + num, 2.467
            --新纪录
            --elseif checkNumber(data.isNew) == 1  then
            --    return 20 + num, 2.467
            --else
            --    return 30 + num, 2.467
            --end
        end
    end
    return 10, 2.467
end

--失败表现
function UIFishPoolGoFishingDialog:FillFailInfo(type)
    self:ClearFailCo()
    KTool.SetActive(self.FishFailTipsGroup, true)

    local resultStr, textContentStr = "", ""
    if type == ConstantsFishing.FishFinishType.BreakLine then
        resultStr = localize("鱼线断了")
        textContentStr = localize("请控制力度")
    elseif type == ConstantsFishing.FishFinishType.BreakFree then
        resultStr = localize("鱼儿跑了")
        textContentStr = localize("请控制力度")
    elseif type == ConstantsFishing.FishFinishType.DisExceed then
        resultStr = localize("鱼线断了")
        textContentStr = localize("请换用更长的鱼线")
    end
    CfUtils.FillText(self.TextTitle, resultStr)
    CfUtils.FillText(self.TextContent, textContentStr)
    self._failCo = cs_coroutine.start(function()
        CfUtils.PlayAnimator(self.AnimRoot, "Play")
        coroutine.yield(WaitForSeconds(2))
        KTool.SetActive(self.FishFailTipsGroup, false)
    end)
end

function UIFishPoolGoFishingDialog:ClearFailCo()
    if self._getFishCo then
        cs_coroutine.stop(self._getFishCo)
        self._getFishCo = nil
    end

    if self._failCo then
        cs_coroutine.stop(self._failCo)
        self._failCo = nil
    end

    if self._castCo then
        cs_coroutine.stop(self._castCo)
        self._castCo = nil
    end
end 

--刷新界面
function UIFishPoolGoFishingDialog:OnFishGoodsChange()
    self:FillFishingPropsInfo()
    self:OnFishActivityCurrencyChange()
end

--刷新是否是引导
function UIFishPoolGoFishingDialog:RefreshIsGuide()
    self._isGuide = false --GuideUtils.IsInGuiding()         --是否是引导
end

--钓鱼激活或停止
function UIFishPoolGoFishingDialog:OnFishActive(body)
    if not body then
        return
    end
    self._enForceStop = checkBool(body.isStop)
end

function UIFishPoolGoFishingDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetTopCommonCb(function()
            if not FishingUtils.IsAutoing() then 
                UIModule.BackDialog()            
            end
        end)

        -- SceneManagement:GetInstance():SetActive(Constants.IdSceneSetting1, false)
        SceneManagement:GetInstance():SetActive(FishingMgr:GetInstance():GetCurFishSceneId(), true)

        local go = GameUtils.GetRedPointGo(self.BtnFishAtlas)
        local num = redPointCom:GetNodeNum(Constants.RedPointConst["PhoneFishCollection"..self._curFishingPlaceId])
        CfUtils.SetActive(go, num > 0) 
    end))
    return coWait
end

function UIFishPoolGoFishingDialog:OnCaptureAction()
    if not self._isNotClearScene then
        print('--->>', self._isNotClearScene)
        -- capture screen
        local effectBg = self.controller.gameObject:GetComponent(typeof(UIEffectCapturedImage))
        if effectBg then
            effectBg:Capture()
        end
        cs_coroutine.yield_return(Yielders.EndOfFrame)
        cs_coroutine.yield_return(FishingMgr:GetInstance():Clear())
    end
end

function UIFishPoolGoFishingDialog:OnHide()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.ResetNavigatorCustomBackAction()
        cs_coroutine.yield_return(self:OnCaptureAction())
        --if FishingMgr:GetInstance():GetIsGoHome() then
        --    Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        --end

        if not self._isNotClearScene then
            cs_coroutine.yield_return(FishingMgr:GetInstance():Clear())
        end
    end))
    return coWait
end

function UIFishPoolGoFishingDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CriWareUtils.RemoveCueSheet(UISheets.SFX_Fishing.path)
        if not IsNull(ScreenTouchEffectModule) then
            KTool.SetActive(ScreenTouchEffectModule.Instance.gameObject, true)
        end
        if not isNull(self._behaviourAction) then
            self._behaviourAction.UpdateAction = nil
        end
        Events.RemoveListener(Constants.EventNames.FishFinish, self.EventFishFinish)
        Events.RemoveListener(Constants.EventNames.FishGoodsChange, self.EventFishGoodsChange)
        Events.RemoveListener(Constants.EventNames.FishActive, self.EventFishActive)
        Events.RemoveListener(Constants.EventNames.OnMonthCardExpired, self.EventMonthCardStop)
        CfUtils.SetTopActive(true)
        if FishingMgr:GetInstance():GetIsGoHome() then
            Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
        end

        self:ClearFailCo()
        if self._finishCo then
            cs_coroutine.stop(self._finishCo)
            self._finishCo = nil
        end

        if self._fixCo then
            cs_coroutine.stop(self._fixCo)
            self._fixCo = nil
        end

        if self._waitTalkCo then
            cs_coroutine.stop(self._waitTalkCo)
            self._waitTalkCo = nil
        end

        if not isNull(self._activityLoader) then
            self._activityLoader:Release()
        end
        
        if self._autoUnlockCo then
            cs_coroutine.stop(self._autoUnlockCo)
            self._autoUnlockCo = nil
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFishPoolGoFishingDialog
